/**
 * Data facade — the only module allowed to touch the validated Stage 1 JSON.
 * Components read numbers exclusively through these exports, so every value on
 * screen traces to `data/` (regenerated by scripts/extract_data.py) and ships
 * with its integrity metadata.
 */
import niOverall from "./source/ni_overall.json";
import lgdResults from "./source/lgd_results.json";
import pcAreaResults from "./source/postcode_area_results.json";
import pcSectorResults from "./source/postcode_sector_results.json";
import classifications from "./source/classifications.json";
import surveyInputs from "./source/survey_inputs.json";
import methodology from "./source/methodology.json";
import metadata from "./source/metadata.json";
import rankings from "./source/theme_rankings.json";
import keyFindings from "./source/key_findings.json";
import subscores from "./source/subscore_comparisons.json";

export type ThemeId = "access_to" | "access_within" | "quality" | "benefits";
export type MetricId = ThemeId | "total";
export type FormatId = "pct" | "index";

export interface ThemesIndex {
  access_to: number;
  access_within: number;
  quality: number;
  benefits: number;
}

export interface LgdResult {
  report_name: string;
  lad_code: string;
  total_pct: number;
  total_index: number;
  themes_index: ThemesIndex;
}

export interface PostcodeResult {
  place: string;
  total_pct: number;
  total_index: number;
  themes_index: ThemesIndex;
  sample_n: number;
  source_label_note?: string;
}

export const THEME_ORDER: ThemeId[] = [
  "access_to",
  "access_within",
  "quality",
  "benefits",
];

export const THEME_LABELS: Record<MetricId, string> = {
  total: "Overall Greenspace Index",
  access_to: "Accessibility To Greenspace",
  access_within: "Access Within Greenspace",
  quality: "Quality",
  benefits: "Benefits",
};

export const THEME_SHORT: Record<MetricId, string> = {
  total: "Overall",
  access_to: "Access To",
  access_within: "Access Within",
  quality: "Quality",
  benefits: "Benefits",
};

/** Display names for councils (official LAD names, & for compactness). */
export const LGD_DISPLAY: Record<string, string> = {
  N09000001: "Antrim & Newtownabbey",
  N09000002: "Armagh City, Banbridge & Craigavon",
  N09000003: "Belfast",
  N09000004: "Causeway Coast & Glens",
  N09000005: "Derry City & Strabane",
  N09000006: "Fermanagh & Omagh",
  N09000007: "Lisburn & Castlereagh",
  N09000008: "Mid & East Antrim",
  N09000009: "Mid Ulster",
  N09000010: "Newry, Mourne & Down",
  N09000011: "Ards & North Down",
};

export const ni = {
  totalPct: niOverall.total_pct as number, // 77
  themesPct: niOverall.themes_pct as Record<ThemeId, number>, // 65/81/80/83
};

export const lgd: LgdResult[] = lgdResults as LgdResult[];
export const lgdByCode: Record<string, LgdResult> = Object.fromEntries(
  lgd.map((r) => [r.lad_code, r]),
);

export const postcodeAreas = pcAreaResults as (PostcodeResult & {
  postcode_area: string;
})[];
export const postcodeSectors = pcSectorResults as (PostcodeResult & {
  postcode_sector: string;
})[];

export { classifications, surveyInputs, methodology, metadata, rankings, keyFindings, subscores };

/** Integrity metadata every area surface must be able to show. */
export const integrity = {
  source: "Development of Greenspace Standard Index — Interim Report v2 (56 Degree Insight for Outscape, July 2026)",
  survey: "POMNI 2025 · 4,000 respondents",
  status: "Proposed methodology · interim results, subject to refinement",
  basis: "Survey perceptions — not objective measurements of greenspace provision",
  threshold: "Postcode geographies reported only at n ≥ 30 respondents",
  moe: "95% margins of error ≈ ±8pp (n≈150) to ±18pp (n=30) for postcode geographies",
  significance: "Differences between areas are descriptive and may not be statistically significant",
  lgdSamples: "Council-level sample sizes are not published in the interim report",
};

/** Formatting helpers (display only — never transforms the published values). */
export const fmtPct = (v: number) => `${Math.round(v)}%`;
export const fmtPct1 = (v: number) => `${v.toFixed(1)}%`;
export const fmtIndex = (v: number) => v.toFixed(1);
export const fmtIndexInt = (v: number) => `${Math.round(v)}`;
